import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';

interface Property {
  id: string;
  title: string;
  description: string;
  location: string;
  shortLocation: string;
  pricePerNight: number;
  totalPrice?: number;
  rating: number;
  reviewsCount: number;
  images: string[];
  features: string[];
  includedExperiences: string[];
  type: 'finca' | 'cabana' | 'hacienda' | 'glamping';
  amenities: string[];
  isSuperhost: boolean;
  hasOffers: boolean;
  isFavorite: boolean;
  coordinates: { lat: number; lng: number };
}

interface SearchParams {
  destination: string;
  checkIn: string;
  checkOut: string;
  guests: number;
}

interface Filters {
  priceMin: number;
  priceMax: number;
  propertyTypes: {
    finca: boolean;
    cabana: boolean;
    hacienda: boolean;
    glamping: boolean;
  };
  experiences: {
    coffeTour: boolean;
    hiking: boolean;
    birdwatching: boolean;
    thermalSprings: boolean;
  };
  amenities: {
    wifi: boolean;
    parking: boolean;
    pool: boolean;
    kitchen: boolean;
    breakfast: boolean;
  };
  minRating: number;
}

@Component({
  selector: 'app-search-results',
  templateUrl: './search-results.component.html',
  styleUrls: ['./search-results.component.scss']
})
export class SearchResultsComponent implements OnInit {
  
  // Datos de búsqueda
  searchParams: SearchParams = {
    destination: '',
    checkIn: '',
    checkOut: '',
    guests: 1
  };

  // Filtros
  filters: Filters = {
    priceMin: 0,
    priceMax: 500000,
    propertyTypes: {
      finca: false,
      cabana: false,
      hacienda: false,
      glamping: false
    },
    experiences: {
      coffeTour: false,
      hiking: false,
      birdwatching: false,
      thermalSprings: false
    },
    amenities: {
      wifi: false,
      parking: false,
      pool: false,
      kitchen: false,
      breakfast: false
    },
    minRating: 0
  };

  // Propiedades y resultados
  allProperties: Property[] = [];
  filteredProperties: Property[] = [];
  paginatedProperties: Property[] = [];

  // Configuración de vista
  viewMode: 'list' | 'map' = 'list';
  sortBy: string = 'relevance';
  
  // Paginación
  currentPage: number = 1;
  itemsPerPage: number = 10;
  totalPages: number = 1;

  constructor(
    private route: ActivatedRoute,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initializeData();
    this.loadSearchParams();
    this.performSearch();
  }

  initializeData(): void {
    // Datos mock de propiedades del Quindío
    this.allProperties = [
      {
        id: '1',
        title: 'Finca Cafetera El Mirador',
        description: 'Auténtica finca cafetera con vista panorámica al Valle de Cocora. Incluye tour completo del proceso del café y degustación.',
        location: 'Salento, Quindío',
        shortLocation: 'Salento',
        pricePerNight: 85000,
        rating: 4.9,
        reviewsCount: 127,
        images: [
          'assets/images/finca-salento-1.jpg',
          'assets/images/finca-salento-2.jpg'
        ],
        features: ['Tour de Café', 'Desayuno Paisa', 'Senderismo', 'Vista Panorámica'],
        includedExperiences: ['Tour de Café', 'Degustación', 'Desayuno Tradicional'],
        type: 'finca',
        amenities: ['wifi', 'parking', 'breakfast'],
        isSuperhost: true,
        hasOffers: false,
        isFavorite: false,
        coordinates: { lat: 4.6397, lng: -75.5644 }
      },
      {
        id: '2',
        title: 'Cabaña Palmas de Cera',
        description: 'Cabaña ecológica en el corazón del Valle de Cocora, rodeada de las majestuosas palmas de cera más altas del mundo.',
        location: 'Valle de Cocora, Salento',
        shortLocation: 'Valle de Cocora',
        pricePerNight: 120000,
        rating: 4.8,
        reviewsCount: 89,
        images: [
          'assets/images/cabana-cocora-1.jpg',
          'assets/images/cabana-cocora-2.jpg'
        ],
        features: ['Vista Palmas', 'Eco-amigable', 'Senderismo', 'Observación de Aves'],
        includedExperiences: ['Senderismo Guiado', 'Avistamiento de Aves'],
        type: 'cabana',
        amenities: ['wifi', 'kitchen'],
        isSuperhost: false,
        hasOffers: true,
        isFavorite: false,
        coordinates: { lat: 4.6336, lng: -75.4728 }
      },
      {
        id: '3',
        title: 'Hacienda Balcón del Quindío',
        description: 'Hacienda tradicional restaurada con arquitectura colonial paisa. Vista espectacular desde el "Balcón del Quindío".',
        location: 'Filandia, Quindío',
        shortLocation: 'Filandia',
        pricePerNight: 150000,
        rating: 4.7,
        reviewsCount: 156,
        images: [
          'assets/images/hacienda-filandia-1.jpg',
          'assets/images/hacienda-filandia-2.jpg'
        ],
        features: ['Arquitectura Colonial', 'Vista Panorámica', 'Cultura Paisa', 'Jardines'],
        includedExperiences: ['Tour Cultural', 'Gastronomía Paisa'],
        type: 'hacienda',
        amenities: ['wifi', 'parking', 'pool', 'breakfast'],
        isSuperhost: true,
        hasOffers: false,
        isFavorite: false,
        coordinates: { lat: 4.6758, lng: -75.6636 }
      },
      {
        id: '4',
        title: 'Glamping Bosques del Quindío',
        description: 'Experiencia de glamping única en medio del bosque húmedo. Perfecto para desconectarse y conectar con la naturaleza.',
        location: 'Montenegro, Quindío',
        shortLocation: 'Montenegro',
        pricePerNight: 200000,
        rating: 4.6,
        reviewsCount: 78,
        images: [
          'assets/images/glamping-montenegro-1.jpg',
          'assets/images/glamping-montenegro-2.jpg'
