  loadSearchParams(): void {
    this.route.queryParams.subscribe(params => {
      this.searchParams.destination = params['destination'] || '';
      this.searchParams.checkIn = params['checkIn'] || '';
      this.searchParams.checkOut = params['checkOut'] || '';
      this.searchParams.guests = parseInt(params['guests']) || 1;
    });
  }

  performSearch(): void {
    this.filteredProperties = [...this.allProperties];
    
    // Filtrar por destino
    if (this.searchParams.destination) {
      this.filteredProperties = this.filteredProperties.filter(property => 
        property.location.toLowerCase().includes(this.searchParams.destination.toLowerCase())
      );
    }

    this.applyFilters();
  }

  applyFilters(): void {
    let filtered = [...this.allProperties];

    // Filtrar por destino de búsqueda
    if (this.searchParams.destination) {
      filtered = filtered.filter(property => 
        property.location.toLowerCase().includes(this.searchParams.destination.toLowerCase())
      );
    }

    // Filtrar por precio
    if (this.filters.priceMin > 0) {
      filtered = filtered.filter(property => property.pricePerNight >= this.filters.priceMin);
    }
    if (this.filters.priceMax > 0) {
      filtered = filtered.filter(property => property.pricePerNight <= this.filters.priceMax);
    }

    // Filtrar por tipo de propiedad
    const selectedTypes = Object.entries(this.filters.propertyTypes)
      .filter(([key, value]) => value)
      .map(([key, value]) => key);
    
    if (selectedTypes.length > 0) {
      filtered = filtered.filter(property => selectedTypes.includes(property.type));
    }

    // Filtrar por calificación
    if (this.filters.minRating > 0) {
      filtered = filtered.filter(property => property.rating >= this.filters.minRating);
    }

    // Filtrar por amenidades
    const selectedAmenities = Object.entries(this.filters.amenities)
      .filter(([key, value]) => value)
      .map(([key, value]) => key);
    
    if (selectedAmenities.length > 0) {
      filtered = filtered.filter(property => 
        selectedAmenities.some(amenity => property.amenities.includes(amenity))
      );
    }

    this.filteredProperties = filtered;
    this.sortProperties();
    this.updatePagination();
  }

  sortProperties(): void {
    switch (this.sortBy) {
      case 'price-low':
        this.filteredProperties.sort((a, b) => a.pricePerNight - b.pricePerNight);
        break;
      case 'price-high':
        this.filteredProperties.sort((a, b) => b.pricePerNight - a.pricePerNight);
        break;
      case 'rating':
        this.filteredProperties.sort((a, b) => b.rating - a.rating);
        break;
      case 'newest':
        // Ordenar por algún criterio de fecha
        break;
      default:
        // Relevancia - mantener orden original
        break;
    }
    this.updatePagination();
  }

  updatePagination(): void {
    this.totalPages = Math.ceil(this.filteredProperties.length / this.itemsPerPage);
    const startIndex = (this.currentPage - 1) * this.itemsPerPage;
    const endIndex = startIndex + this.itemsPerPage;
    this.paginatedProperties = this.filteredProperties.slice(startIndex, endIndex);
  }

  // Métodos de filtros
  setPriceRange(min: number, max: number): void {
    this.filters.priceMin = min;
    this.filters.priceMax = max;
    this.applyFilters();
  }

  setMinRating(rating: number): void {
    this.filters.minRating = rating;
    this.applyFilters();
  }

  clearFilters(): void {
    this.filters = {
      priceMin: 0,
      priceMax: 500000,
      propertyTypes: {
        finca: false,
        cabana: false,
        hacienda: false,
        glamping: false
      },
      experiences: {
        coffeTour: false,
        hiking: false,
        birdwatching: false,
        thermalSprings: false
      },
      amenities: {
        wifi: false,
        parking: false,
        pool: false,
        kitchen: false,
        breakfast: false
      },
      minRating: 0
    };
    this.applyFilters();
  }

  // Métodos de vista
  setViewMode(mode: 'list' | 'map'): void {
    this.viewMode = mode;
  }

  // Métodos de paginación
  goToPage(page: number): void {
    if (page >= 1 && page <= this.totalPages) {
      this.currentPage = page;
      this.updatePagination();
    }
  }

  getPageNumbers(): number[] {
    const pages: number[] = [];
    const maxPagesToShow = 5;
    const half = Math.floor(maxPagesToShow / 2);
    
    let start = Math.max(1, this.currentPage - half);
    let end = Math.min(this.totalPages, start + maxPagesToShow - 1);
    
    if (end - start + 1 < maxPagesToShow) {
      start = Math.max(1, end - maxPagesToShow + 1);
    }
    
    for (let i = start; i <= end; i++) {
      pages.push(i);
    }
    
    return pages;
  }

  // Métodos de utilidad
  getDestinationName(destination: string): string {
    const destinations: { [key: string]: string } = {
      'salento': 'Salento',
      'valle-cocora': 'Valle de Cocora',
      'filandia': 'Filandia',
      'armenia': 'Armenia',
      'calarca': 'Calarcá',
      'montenegro': 'Montenegro',
      'quimbaya': 'Quimbaya',
      'circasia': 'Circasia',
      'la-tebaida': 'La Tebaida',
      'buenavista': 'Buenavista'
    };
    return destinations[destination] || destination;
  }

  trackByPropertyId(index: number, property: Property): string {
    return property.id;
  }

  // Métodos de acción
  toggleFavorite(propertyId: string): void {
    const property = this.allProperties.find(p => p.id === propertyId);
    if (property) {
      property.isFavorite = !property.isFavorite;
    }
  }

  viewProperty(propertyId: string): void {
    this.router.navigate(['/property', propertyId]);
  }

  quickBook(propertyId: string): void {
    this.router.navigate(['/booking'], { 
      queryParams: { 
        propertyId: propertyId,
        checkIn: this.searchParams.checkIn,
        checkOut: this.searchParams.checkOut,
        guests: this.searchParams.guests
      }
    });
  }

